INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 0, "2030/12/17 14:59:59", 110501, 1, 24015, 4, 4, 0, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 4, "2030/12/17 14:59:59", 110501, 2, 24016, 4, 1, 0, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 0, "2030/12/17 14:59:59", 110501, 3, 24017, 4, 4, 0, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 5.2, "2030/12/17 14:59:59", 110501, 4, 24018, 1, 2, 0, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 4.2, "2030/12/17 14:59:59", 110501, 5, 24019, 5, 6, 0, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 0, "2030/12/17 14:59:59", 110501, 6, 24020, 2, 2, 0, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 6.4, "2030/12/17 14:59:59", 110501, 7, 24021, 1, 6, 0, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 0, "2030/12/17 14:59:59", 110501, 8, 24022, 2, 2, 0, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 10.08, "2030/12/17 14:59:59", 110501, 9, 24023, 6, 3, 0, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 5, "2030/12/17 14:59:59", 110501, 10, 24024, 1, 2, 0, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 0, 24, "2019/07/31 12:00:00");
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("カオリ（サマー）", 10021, 0, "2030/12/17 14:59:59", 110501, 11, 24025, 2, 2, 0, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 0, 24, "2019/07/31 12:00:00");
